style.css:
@-moz-document domain("youtube.com") {
/* Background color for the main body */
  body {
    background-color: #f9f0ff !important; /* Lavender */
    color: #4b4b63 !important; /* Dark lavender text */
  }

  /* Header and top navigation bar */
  #masthead-container {
    background-color: #e6ffe6 !important; /* Mint Green */
  }

  /* Sidebar background */
  #guide {
    background-color: #e6ffe6 !important; /* Mint Green */
  }

  /* Video titles */
  #video-title {
    color: #4b4b63 !important; /* Dark lavender text */
  }

  /* Buttons (Like, Subscribe, etc.) */
  .yt-spec-button-shape-next--solid {
    background-color: #e6ffe6 !important; /* Mint Green */
    color: #4b4b63 !important; /* Lavender text */
    border-radius: 8px !important; /* Rounded edges */
    border: 1px solid #bdebbd !important; /* Light green border */
  }

  /* Search bar */
  #search-form {
    background-color: #f9f0ff !important; /* Lavender */
    border-radius: 12px !important; /* Rounded edges */
    border: 1px solid #e0d7ff !important; /* Subtle lavender border */
  }

  /* Video thumbnails */
  ytd-thumbnail {
    border-radius: 12px !important; /* Rounded edges */
    background-color: #e6ffe6 !important; /* Mint Green */
  }

  /* Footer */
  #footer {
    background-color: #f9f0ff !important; /* Lavender */
    color: #4b4b63 !important; /* Lavender text */
  }

  /* Main content background */
  ytd-app {
    background-color: #f9f0ff !important; /* Lavender */
  }
}
